begin;
do $$
declare previous jsonb; next_documents jsonb;
begin
 select documents into strict previous from public.legal_releases where version='2026-11-05.1' and not enabled;
 if md5(previous::text)<>'dd1d02eb2d4fa4b1b99eebec3d05c242' then raise exception 'El borrador base no coincide; no continuar.'; end if;
 next_documents := jsonb_set(jsonb_set(jsonb_set(previous, '{version}', '"2026-11-10.1"'::jsonb), '{operator,address}', to_jsonb('Transversal 96B 20D 70, Bogotá, Colombia'::text)), '{operator,emailVerified}', 'true'::jsonb);
 next_documents := jsonb_set(next_documents, '{policies,/terminos,sections,1,1}', $policy$"MiBatute es un sitio de clasificados con chat entre usuarios y actúa como portal de contacto según el artículo 53 de la Ley 1480 de 2011. El comprador y el vendedor acuerdan directamente el precio, el pago y la entrega. Las reservas y los estados del anuncio sirven para organizar la publicación y la conversación. MiBatute no vende los artículos de los usuarios, no recibe su precio, no coordina envíos, no garantiza su estado ni entrega y no decide ni tramita devoluciones entre usuarios. Quien publica responde por su oferta y por las obligaciones que le correspondan. MiBatute atiende sus obligaciones legales y responde por los servicios que presta directamente."$policy$::jsonb);
 next_documents := jsonb_set(next_documents, '{policies,/terminos,sections,8,1}', $policy$"El chat de un artículo es de acceso restringido a sus participantes y al personal autorizado cuando sea necesario para atender reportes de seguridad, solicitudes de identificación de oferentes o requerimientos legales. El buzón de soporte lo comparten admin y superadmin. Una conversación común nueva se limita a una cada 24 horas; sus mensajes y respuestas tienen máximo 500 caracteres. Las solicitudes de datos personales utilizan un canal separado sin ese límite de 24 horas."$policy$::jsonb);
 next_documents := jsonb_set(next_documents, '{policies,/privacidad,sections,3,1}', $policy$"Las publicaciones muestran información del artículo y ubicación general. Correo, teléfono y dirección de la cuenta no se publican como parte del perfil público. Las imágenes y textos que publiques pueden ser vistos y copiados por otras personas: revisa que no revelen datos privados. Los accesos administrativos se limitan por funciones. Para el registro de oferentes se recogen nombre o razón social, documento de identificación, dirección física de notificaciones y teléfono. El registro es privado. El personal autorizado puede facilitar la identificación por un canal privado a quien acredite la compra y la necesite para presentar una queja o reclamo, o a la autoridad competente que la solicite, conforme al artículo 53 de la Ley 1480 de 2011."$policy$::jsonb);
 next_documents := jsonb_set(next_documents, '{policies,/pagos,sections,0,1}', $policy$"El comprador y el vendedor acuerdan directamente el pago y la entrega del artículo. MiBatute no recauda ese pago ni tramita devoluciones del artículo. Los créditos son para funciones de MiBatute. Las reglas de recargas y reembolsos de esta página se refieren a servicios propios de la plataforma."$policy$::jsonb);
 if md5(next_documents::text)<>'f12f05764449c70e744ed4ec032e23ae' then raise exception 'El nuevo borrador no coincide.'; end if;
 insert into public.legal_releases(version,documents,enabled,published_at) values('2026-11-10.1',next_documents,false,clock_timestamp()) on conflict(version) do nothing;
 if not exists(select 1 from public.legal_releases where version='2026-11-10.1' and not enabled and documents=next_documents) then raise exception 'La versión existente difiere; no sobrescribir.'; end if;
end;
$$;
commit;
